// Alertmanager payload 의 첫 번째 알람만 처리 (groupBy=namespace,pod,container)
const body = $input.first().json.body || $input.first().json;
const alert = (body.alerts && body.alerts[0]) || {};
const labels = alert.labels || {};
const annotations = alert.annotations || {};

return [{
  json: {
    alertname:   labels.alertname || 'Unknown',
    namespace:   labels.namespace || labels.exported_namespace || 'default',
    pod:         labels.pod || '',
    container:   labels.container || 'api',
    severity:    labels.severity || 'unknown',
    summary:     annotations.summary || '',
    description: annotations.description || '',
    raw:         body
  }
}];

// 3 HTTP 결과 + parsed alert 를 합쳐서 LLM 입력 prompt 생성.
// n8n 의 mergeBy/expression 만으로 묶기 까다로워서 모든 input 을 Code 에서 합침.
const alertItem = $('Parse Alert').first().json;
const pod    = $('K8s GET pod').first().json || {};
const logsItem = $('K8s GET pod logs (previous)').first();
const logsJson = (logsItem && logsItem.json) || {};
const logs = (typeof logsJson === 'string') ? logsJson
  : (logsJson.data ?? logsJson.body ?? logsJson.text ?? (logsItem && logsItem.binary ? '' : ''));
const events = $('K8s GET events').first().json || {};

// describe-style 요약 (전체 dump 는 너무 길어서 핵심만)
const container = (pod.spec && pod.spec.containers && pod.spec.containers[0]) || {};
const lastState = ((pod.status && pod.status.containerStatuses && pod.status.containerStatuses[0]) || {}).lastState || {};
const describe = [
  `Name:      ${pod.metadata && pod.metadata.name}`,
  `Namespace: ${pod.metadata && pod.metadata.namespace}`,
  `Status:    ${pod.status && pod.status.phase}`,
  `Container: ${container.name} (${container.image})`,
  `Limits:    ${JSON.stringify(container.resources && container.resources.limits)}`,
  `Requests:  ${JSON.stringify(container.resources && container.resources.requests)}`,
  `LastState: ${JSON.stringify(lastState)}`,
].join('\n');

const logsText = logs ? String(logs).split('\n').slice(-80).join('\n') : '(no previous logs available)';

const eventLines = (events.items || []).slice(-15).map(e =>
  `${e.lastTimestamp || e.eventTime || ''}  ${e.type}  ${e.reason}  ${e.message}`
).join('\n');

const userPrompt = `[ALERT]\n${JSON.stringify({
  alertname: alertItem.alertname,
  severity:  alertItem.severity,
  summary:   alertItem.summary,
})}\n\n[POD]\nnamespace: ${alertItem.namespace}\nname:      ${alertItem.pod}\ncontainer: ${alertItem.container}\n\n[POD describe (truncated)]\n${describe}\n\n[Container logs — previous instance, last 80 lines]\n${logsText}\n\n[Recent events]\n${eventLines}`;

const systemPrompt = `You are a senior Kubernetes SRE and JVM/Python operations expert.\nReturn JSON only, schema: {"root_cause":str,"confidence":int,"evidence":[str]}`;

return [{
  json: {
    alert: alertItem,
    pod_summary: describe,
    logs_text: logsText,
    events_text: eventLines,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    // RL stub 입력에 사용할 메트릭 추정치
    current_limit_mb: parseInt((container.resources && container.resources.limits && container.resources.limits.memory || '128Mi').replace(/[^0-9]/g, '')) || 128,
    restart_count: ((pod.status && pod.status.containerStatuses && pod.status.containerStatuses[0]) || {}).restartCount || 0,
  }
}];

// Ollama 응답에서 message.content (JSON 문자열) 파싱
const raw = ($input.first().json.message && $input.first().json.message.content) || '{}';
let parsed = { root_cause: 'unknown', confidence: 0, evidence: [] };
try {
  parsed = JSON.parse(raw);
} catch (e) {
  // LLM 이 코드 블록 포함하는 경우 fence 제거 후 재시도
  const stripped = raw.replace(/^```json\s*/, '').replace(/```$/, '').trim();
  try { parsed = JSON.parse(stripped); } catch (_) {}
}
const prev = $('Build LLM Prompt').first().json;
return [{ json: { ...prev, diagnosis: parsed } }];

const prev = $('Parse LLM JSON').first().json;
const rl = $input.first().json;
return [{ json: { ...prev, remediation: rl } }];

