// Slack 은 application/x-www-form-urlencoded 로 'payload=<JSON>' 형태로 보낸다.
const body = $input.first().json.body || $input.first().json;
let payload;
if (typeof body === 'string') {
  // rawBody → 'payload=...' 디코드
  const m = body.match(/payload=(.+)/);
  payload = m ? JSON.parse(decodeURIComponent(m[1].replace(/\+/g, ' '))) : {};
} else if (body.payload) {
  payload = typeof body.payload === 'string' ? JSON.parse(body.payload) : body.payload;
} else {
  payload = body;
}
const action = (payload.actions && payload.actions[0]) || {};
let decision = {};
try { decision = JSON.parse(action.value || '{}'); } catch (_) {}
return [{
  json: {
    action_id:   action.action_id || 'unknown',
    user:        (payload.user && payload.user.name) || 'unknown',
    decision:    decision,
    response_url: payload.response_url
  }
}];

